ransform:scale(1.08);filter:saturate(1.05)}.trc-liens a::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(22,10,6,0) 35%,rgba(22,10,6,.9))}.trc-liens span{position:absolute;left:1.2rem;right:1.2rem;bottom:1rem;z-index:1;font-family:"Cormorant Garamond",Georgia,serif;font-size:1.6rem;font-weight:700;line-height:1.1}.trc-liens span::after{content:"→";display:inline-block;margin-left:.5rem;color:#d9a441;transition:transform .3s}.trc-liens a:hover span::after{transform:translateX(5px)}@media (max-width:980px){.trc-frise ol{grid-template-columns:repeat(2,1fr)}.trc-jours,.trc-liens{grid-template-columns:1fr 1fr}}@media (max-width:600px){.trc-frise ol,.trc-jours,.trc-liens{grid-template-columns:1fr}}@media (prefers-reduced-motion:reduce){.trc *{transition:none!important}.trc-rv{opacity:1;transform:none}}</style><div class="page-section trc trc-frise"><div class="trc-in"><span class="trc-k">Repères</span><h2>Quatre siècles en dix dates</h2><p class="trc-chapo">Des royaumes du Danxomè et de Hogbonou à l’indépendance, les grandes étapes qui ont façonné les sites que vous visiterez.</p><ol><li class="trc-rv" style="--d:0ms"><b>1645</b><p>Houegbadja fonde le royaume du Danxomè, avec Abomey pour capitale.</p></li><li class="trc-rv" style="--d:60ms"><b>Vers 1688</b><p>Te Agbanlin fonde le royaume de Hogbonou, future Porto-Novo.</p></li><li class="trc-rv" style="--d:120ms"><b>1727</b><p>Le roi Agadja prend Savi et Ouidah : le Danxomè atteint la côte.</p></li><li class="trc-rv" style="--d:180ms"><b>1892</b><p>Abomey tombe le 17 novembre, au terme de la résistance menée par Béhanzin.</p></li><li class="trc-rv" style="--d:240ms"><b>1894</b><p>Béhanzin se rend ; le Danxomè passe sous domination coloniale.</p></li><li class="trc-rv" style="--d:300ms"><b>1960</b><p>Le 1er août, le Dahomey accède à l’indépendance.</p></li><li class="trc-rv" style="--d:360ms"><b>1975</b><p>Le Dahomey prend le nom de Bénin.</p></li><li class="trc-rv" style="--d:420ms"><b>1985</b><p>Les palais royaux d’Abomey entrent au patrimoine mondial de l’UNESCO.</p></li><li class="trc-rv" style="--d:480ms"><b>1995</b><p>La Porte du Non-Retour est inaugurée sur la plage de Ouidah.</p></li><li class="trc-rv" style="--d:540ms"><b>2021</b><p>Retour au Bénin de 26 trésors royaux d’Abomey.</p></li></ol></div></div><div class="page-section trc trc-it"><div class="trc-in"><span class="trc-k">Itinéraire</span><h2>Le triangle historique en trois jours</h2><p class="trc-chapo">Au départ de Cotonou, trois villes, trois histoires : la capitale aux trois noms, la cité de la mémoire et la capitale royale.</p><div class="trc-jours"><a class="trc-jour trc-rv" style="--d:0ms" href="/explorez/les-cinq-benin/porto-novo"><figure><img src="/assets/img/wikimedia/porto-novo-musee-honme.webp" alt="Porto-Novo" loading="lazy" decoding="async"><span>Jour 1</span></figure><div><h3>Porto-Novo</h3><small>À 45 minutes de Cotonou</small><p>Musée Honmè, ancien palais royal · Grande Mosquée · maisons afro-brésiliennes · musée da Silva</p><i>Préparer l’étape →</i></div></a><a class="trc-jour trc-rv" style="--d:100ms" href="/activites/sur-les-traces-de-lhistoire/la-route-de-lesclave"><figure><img src="/assets/img/ouidah-musee-1200x600.webp" alt="Ouidah" loading="lazy" decoding="async"><span>Jour 2</span></figure><div><h3>Ouidah</h3><small>À environ 1 h de Cotonou</small><p>Route de l’Esclave · Porte du Non-Retour · Fort portugais · forêt sacrée de Kpassè · temple des Pythons</p><i>Préparer l’étape →</i></div></a><a class="trc-jour trc-rv" style="--d:200ms" href="/explorez/terre-de-traditions/les-palais-royaux-dabomey"><figure><img src="/assets/img/abomey-palais-640x480.webp" alt="Abomey" loading="lazy" decoding="async"><span>Jour 3</span></figure><div><h3>Abomey</h3><small>À environ 2 h 30 de Cotonou</small><p>Palais royaux · musée historique · place Goho · ateliers des tentures appliquées</p><i>Préparer l’étape →</i></div></a></div></div></div><div class="page-section trc trc-hub"><div class="trc-in"><span class="trc-k">Approfondir</span><h2>Les lieux de l’Histoire</h2><div class="trc-liens"><a class="trc-rv" style="--d:0ms" href="/activites/sur-les-traces-de-lhistoire/la-route-de-lesclave"><img style="object-position:50% 20%" src="/assets/img/wikimedia/porte-du-non-retour-au-benin.webp" alt="La Route de l’Esclave" loading="lazy" decoding="async"><span>La Route de l’Esclave</span></a><a class="trc-rv" style="--d:70ms" href="/explorez/terre-de-traditions/les-palais-royaux-dabomey"><img style="object-position:50% 20%" src="/assets/img/abomey-basrelief-640x480.webp" alt="Les palais royaux d’Abomey" loading="lazy" decoding="async"><span>Les palais royaux d’Abomey</span></a><a class="trc-rv" style="--d:140ms" href="/explorez/terre-de-traditions/le-royaume-du-danxome"><img style="object-position:50% 20%" src="/assets/img/wikimedia/abomey-goho-glele.webp" alt="Le royaume du Danxomè" loading="lazy" decoding="async"><span>Le royaume du Danxomè</span></a><a class="trc-rv" style="--d:210ms" href="/explorez/terre-de-traditions/les-amazones-du-dahomey"><img style="object-position:50% 20%" src="/assets/img/amazone-640x480.webp" alt="Les Amazones du Dahomey" loading="lazy" decoding="async"><span>Les Amazones du Dahomey</span></a><a class="trc-rv" style="--d:280ms" href="/explorez/les-cinq-benin/porto-novo"><img style="object-position:50% 20%" src="/assets/img/wikimedia/porto-novo-grande-mosquee-facade.webp" alt="Porto-Novo" loading="lazy" decoding="async"><span>Porto-Novo</span></a><a class="trc-rv" style="--d:350ms" href="/explorez/terre-de-traditions/ouidah-ville-du-vodun"><img style="object-position:50% 20%" src="/assets/img/ouidah-pythons-640x480.webp" alt="Ouidah, ville du Vodun" loading="lazy" decoding="async"><span>Ouidah, ville du Vodun</span></a></div></div></div><script>(function(){var e=document.querySelectorAll(".trc-rv");if(!("IntersectionObserver" in window)){e.forEach(function(x){x.classList.add("is-in")});return}var o=new IntersectionObserve